cssHead:
body {
  font-family: 'Geist', sans-serif;
  background-color: #F6F7F4;
  color: #203E35;
  margin: 0;
  padding: 0;
  -webkit-font-smoothing: antialiased;
}
.sphere-logo {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #689D82 0%, #355C4A 55%, #183329 100%);
  box-shadow: 0 0 12px rgba(217, 164, 65, 0.35), inset -2px -2px 5px rgba(0, 0, 0, 0.45), inset 2px 2px 4px rgba(255, 255, 255, 0.35);
}
